body.value:
{%- comment -%} Vídeo da avatar no fim da coleção: autoplay sem som, toque liga/desliga o som. {%- endcomment -%}
<style>
  .pa-vid{max-width:760px;margin:0 auto;padding:28px 16px 12px;text-align:center;color:#4f473f;font:400 14px/1.6 var(--font-body-family,Inter),sans-serif}
  .pa-vid h2{margin:0 0 6px;font-family:'Cormorant Garamond','Times New Roman',serif;font-weight:600;font-size:26px;line-height:1.1;color:#16110c;letter-spacing:0}
  .pa-vid p{margin:0 0 14px}
  .pa-vid__box{position:relative;max-width:340px;margin:0 auto;border-radius:16px;overflow:hidden;background:#16110c;box-shadow:0 8px 28px rgba(22,17,12,.18);cursor:pointer}
  .pa-vid__box video{display:block;width:100%;height:auto;aspect-ratio:9/16;object-fit:cover}
  .pa-vid__som{position:absolute;right:10px;bottom:10px;display:inline-flex;align-items:center;gap:6px;padding:7px 11px;border-radius:999px;background:rgba(22,17,12,.72);color:#fff;font:600 12px/1 var(--font-body-family,Inter),sans-serif;pointer-events:none}
  @media (min-width:750px){ .pa-vid{padding-top:36px} .pa-vid h2{font-size:30px} }
</style>
<div class="pa-vid">
  {%- if section.settings.titulo != blank -%}<h2>{{ section.settings.titulo }}</h2>{%- endif -%}
  {%- if section.settings.texto != blank -%}<p>{{ section.settings.texto }}</p>{%- endif -%}
  <div class="pa-vid__box" onclick="var v=this.querySelector('video'),b=this.querySelector('.pa-vid__som');v.muted=!v.muted;if(!v.muted){v.currentTime=0;v.play();}b.textContent=v.muted?'🔇 Toca para escuchar':'🔊 Sonido activado';">
    {%- if section.settings.video != blank -%}
      {{ section.settings.video | video_tag: autoplay: true, muted: true, loop: true, playsinline: true, controls: false, preload: 'metadata', image_size: '720x' }}
    {%- else -%}
      <video src="{{ section.settings.video_url }}" {% if section.settings.poster != blank %}poster="{{ section.settings.poster | image_url: width: 720 }}"{% endif %} autoplay muted loop playsinline preload="metadata"></video>
    {%- endif -%}
    <span class="pa-vid__som">🔇 Toca para escuchar</span>
  </div>
</div>
{% schema %}
{
  "name": "Vídeo da loja (coleção)",
  "settings": [
    { "type": "text", "id": "titulo", "label": "Título", "default": "Conoce nuestra tienda" },
    { "type": "text", "id": "texto", "label": "Texto curto", "default": "Perfumes árabes en Chile · Pagas al recibir" },
    { "type": "video", "id": "video", "label": "Vídeo (Arquivos)" },
    { "type": "text", "id": "video_url", "label": "URL do vídeo (se não escolher acima)" },
    { "type": "image_picker", "id": "poster", "label": "Capa (poster)" }
  ],
  "presets": [{ "name": "Vídeo da loja (coleção)" }]
}
{% endschema %}

{
  "sections": {
    "pa-topo": {
      "type": "pa-colecao-topo",
      "settings": {
        "eyebrow": "Lattafa · Armaf · Afnan",
        "subtitulo": "Fragancias intensas y duraderas para mujer y hombre.",
        "mostrar_imagem": true,
        "selo_1": "Originales",
        "selo_2": "Paga al recibir",
        "selo_3": "Envío gratis",
        "botao_filtro": true
      }
    },
    "main-collection-product-grid": {
      "type": "main-collection-product-grid",
      "settings": {
        "products_per_page": 24,
        "columns_desktop": 4,
        "image_ratio": "square",
        "show_secondary_image": true,
        "show_vendor": false,
        "show_rating": false,
        "enable_quick_add": true,
        "enable_filtering": true,
        "filter_type": "horizontal",
        "enable_sorting": true,
        "columns_mobile": "2",
        "padding_top": 0,
        "padding_bottom": 28
      }
    },
    "pa-video": {
      "type": "pa-colecao-video",
      "settings": {
        "titulo": "Conoce nuestra tienda",
        "texto": "Perfumes árabes en Chile · Pagas al recibir",
        "video_url": "https://cdn.shopify.com/videos/c/vp/d8e0f8130bd942528017a8333edd7fb6/d8e0f8130bd942528017a8333edd7fb6.HD-720p-1.6Mbps-96983737.mp4",
        "poster": "shopify://shop_images/loja-chile-avatar-poster.jpg"
      }
    },
    "pa-seo": {
      "type": "pa-colecao-seo",
      "settings": {
        "titulo": "Perfumes árabes originales en Chile",
        "usar_descricao": true,
        "texto": "<p>Los perfumes árabes son conocidos por sus notas intensas de ámbar, vainilla, oud y especias, y por su buena duración en la piel. En esta colección encuentras fragancias de casas árabes como Lattafa, Armaf y Afnan, en presentación individual o en kits para ahorrar.</p><p><strong>¿Kit o unitario?</strong> Si ya sabes cuál te gusta, elige el perfume unitario. Si quieres variar según la ocasión o regalar, los kits reúnen varios perfumes en un solo pedido.</p><p><strong>¿Cómo pago?</strong> Pagas al recibir tu pedido en casa, con despacho a todo Chile.</p>"
      }
    }
  },
  "order": [
    "pa-topo",
    "main-collection-product-grid",
    "pa-video",
    "pa-seo"
  ]
}
